<script setup lang="ts">
import IconButton from '../components/IconButton.vue';
import { useEvents } from '../events';
import { ref,computed,onMounted,onUnmounted } from 'vue';import { api,auth } from '../api';import { names,type Channel,type Story } from '../types';import HomeSettings from '../components/HomeSettings.vue';
const settingsTab=ref('模型');
const stories=ref<Story[]>([]),status=ref(''),settings=ref(false),busy=ref(false),guide=ref(false),notifyBusy=ref(false),notifications=ref(false);
const notified=new Map<string,number>();let initialized=false,lastRefresh=0;
const cards=computed(()=>stories.value.flatMap(story=>(Object.keys(names) as Channel[]).map(channel=>({key:story.id+channel,story,channel,title:story.channels?.[channel]?.title||(channel==='group'?(story.title==='原有故事'?names.group:story.title):names[channel]),avatar:channel==='group'?story.avatar:(story.channels?.[channel]?.display_avatar||story.channels?.[channel]?.avatar),activity:story.activity?.[channel]||{}}))).sort((a,b)=>(b.activity.updated_at||0)-(a.activity.updated_at||0)));
async function load(){const fallback='Notification' in window&&Notification.permission==='granted'&&localStorage.getItem('companion-notifications-disabled')!=='true'&&localStorage.getItem('companion-web-push')!=='enabled';if(busy.value||document.hidden&&(!fallback||Date.now()-lastRefresh<60000))return;lastRefresh=Date.now();busy.value=true;try{stories.value=await api<Story[]>('/api/conversations');status.value='';for(const card of cards.value){const stamp=card.activity.incoming_at||0;if(initialized&&document.hidden&&fallback&&stamp>(notified.get(card.key)||0)&&card.activity.unread){const notice=new Notification(card.title,{body:'你收到了一条新消息',tag:card.key});notice.onclick=()=>{window.focus();location.assign('/chat?conversation='+encodeURIComponent(card.story.id)+'&channel='+card.channel);};}notified.set(card.key,stamp);}initialized=true;const unread=cards.value.reduce((n,c)=>n+(c.activity.unread||0),0);document.title=unread?`(${unread}) 会话`:'会话';}catch(e){status.value=(e as Error).message;}finally{busy.value=false;}}
function syncNotification(){notifications.value='Notification' in window&&Notification.permission==='granted'&&(localStorage.getItem('companion-notifications-disabled')!=='true'||localStorage.getItem('companion-notifications-disable-pending')==='true');}
async function toggleNotifications(){notifyBusy.value=true;try{const bridge=(window as unknown as {chatNotifications:{enable():Promise<string>;disable():Promise<string>}}).chatNotifications;status.value=await (notifications.value?bridge.disable():bridge.enable());}catch(e){status.value=(e as Error).message;}finally{syncNotification();notifyBusy.value=false;}}
useEvents(load);
let timer:ReturnType<typeof setInterval>;
onMounted(()=>{load();syncNotification();timer=setInterval(load,30000);document.addEventListener('visibilitychange',load);window.addEventListener('storage',syncNotification);const now=new Date(),key='chat-usage-guide:'+auth.scope+':'+now.toLocaleDateString();if(!localStorage.getItem(key)){guide.value=true;localStorage.setItem(key,'shown');}});
onUnmounted(()=>{clearInterval(timer);document.removeEventListener('visibilitychange',load);window.removeEventListener('storage',syncNotification);});
</script>
<template><div class="home"><aside class="rail"><span class="rail-chat">◌</span><IconButton icon="settings" label="设置" @click="settingsTab='模型';settings=true"/></aside><header><span>会话</span><div><IconButton :icon="notifications?'bell':'bellOff'" :label="notifications?'关闭通知':'开启通知'" @click="toggleNotifications" :busy="notifyBusy" :aria-pressed="notifications"/><IconButton icon="user" :label="auth.username||'账号'" @click="settingsTab='账号';settings=true"/></div></header><main class="story-list"><p v-if="status" class="feedback" role="status">{{status}}</p><p v-if="!cards.length" class="muted empty">{{busy?'正在读取会话…':'暂无会话'}}</p><RouterLink v-for="card in cards" :key="card.key" class="story" :to="{path:'/chat',query:{conversation:card.story.id,channel:card.channel}}"><span class="story-avatar"><img v-if="card.avatar" :src="card.avatar" alt="" decoding="async"><span v-else>{{card.channel==='group'?'群':card.title.slice(0,1)}}</span><b v-if="card.activity.unread">{{card.activity.unread>99?'99+':card.activity.unread}}</b></span><div class="story-copy"><strong>{{card.title}}</strong><p>{{card.activity.preview||''}}</p></div><time>{{card.activity.updated_at?new Date(card.activity.updated_at*1000).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):''}}</time><span class="chevron">›</span></RouterLink></main><HomeSettings :initial-tab="settingsTab" v-if="settings" @close="settings=false;load()" :world="stories[0]?.id||'default'"/><div v-if="guide" class="overlay"><section class="dialog guide" role="dialog" aria-modal="true" aria-labelledby="guideTitle"><h2 id="guideTitle">使用教程</h2><ol><li>在主页左下角「设置 → 模型」填写接口地址、模型名称和 API Key，测试后保存。</li><li>三位角色默认继承主页模型，也可在各自聊天设置里单独配置。</li><li>消息可连续发送。主动消息总开关位于主页设置。</li><li>「MCP」可授权外部客户端，默认使用独立聊天世界。</li></ol><footer><button @click="guide=false">知道了</button><button class="primary" @click="guide=false;settings=true">去配置</button></footer></section></div></div></template>
